const allowed = {
  avatars: { table: 'avatar_catalog', keyColumns: ['avatar'] },
  scenes: { table: 'scene_catalog', keyColumns: ['avatar', 'scene'] },
  assetTypes: { table: 'asset_type_catalog', keyColumns: ['asset_type'] },
  workflows: { table: 'generation_workflow_catalog', keyColumns: ['workflow'] },
  models: { table: 'generation_model_catalog', keyColumns: ['model'] }
};

function sql(value) {
  if (value === undefined || value === null || value === '') return 'NULL';
  return `'${String(value).replace(/'/g, "''")}'`;
}

const body = $json.body || {};
const catalog = body.catalog ?? body.catalogType;
const def = allowed[catalog];

if (!def) {
  throw new Error(`Invalid catalog '${catalog}'. Allowed: ${Object.keys(allowed).join(', ')}`);
}

const payload = {
  avatar: body.avatar,
  scene: body.scene ?? body.value,
  avatar_catalog_value: body.avatar ?? body.value,
  asset_type: body.assetType ?? body.asset_type ?? body.value,
  workflow: body.workflow ?? body.value,
  model: body.model ?? body.value
};

function valueForKey(key) {
  if (catalog === 'avatars' && key === 'avatar') return payload.avatar_catalog_value;
  return payload[key];
}

const whereParts = [];
for (const key of def.keyColumns) {
  const value = valueForKey(key);
  if (!value) {
    throw new Error(`Missing required key '${key}'`);
  }
  whereParts.push(`${key} = ${sql(value)}`);
}

const isEnabled = body.isEnabled === true || body.enable === true;
const disabledReason = body.disabledReason ?? body.disabled_reason ?? null;

const query = `
UPDATE ${def.table}
SET
  is_enabled = ${isEnabled ? 'true' : 'false'},
  ${catalog === 'scenes' ? `is_active = ${isEnabled ? 'true' : 'false'},` : ''}
  disabled_at = ${isEnabled ? 'NULL' : 'now()'},
  disabled_reason = ${isEnabled ? 'NULL' : sql(disabledReason || 'Disabled from dashboard')},
  updated_at = now()
WHERE ${whereParts.join(' AND ')}
RETURNING *;
`;

return { json: { query, catalog, table: def.table, keyColumns: def.keyColumns } };

const items = $input.all();

return [{
  json: {
    ok: true,
    count: items.length,
    item: items.length ? items[0].json : null
  }
}];
